import csv,datetime as dt,hashlib,json,math,statistics,sys
from collections import defaultdict
from pathlib import Path
import pandas as pd
sys.path.insert(0,str(Path("scripts").resolve()))
from finalize_report import common_row_summary
root=Path.cwd()
def read(path):
    return json.loads((root/path).read_text())
def digest(path):
    return hashlib.sha256((root/path).read_bytes()).hexdigest()
main_lock=read("FINAL_EVAL_LOCK.json")
branches={}
for kind in ["author_labels","dd_original"]:
    assert read(f"sensitivity/{kind}/artifacts/PREDICTION_COMPLETENESS.json")["complete"]
    alternative_lock=read(f"sensitivity/{kind}/FINAL_EVAL_LOCK.json")
    main_sources={fold["source"] for fold in main_lock["folds"] if fold["eligible"]}
    alternative_sources={fold["source"] for fold in alternative_lock["folds"] if fold["eligible"]}
    sources=sorted(main_sources&alternative_sources)
    assert len(sources)==4 and "HiTEA 2024" not in sources
    path=f"reports/final/{kind}_paired_common_rows.csv"
    rows=list(csv.DictReader((root/path).open()))
    grouped=defaultdict(lambda:defaultdict(list))
    for row in rows:
        if row["source"] in sources:
            key=(row["model"],row["truth_regime"],row["metric"])
            value=float(row["paired_delta"])
            assert math.isfinite(value)
            grouped[key][row["source"]].append(value)
    computed={}
    for key,by_source in grouped.items():
        assert set(by_source)==set(sources)
        assert all(len(values)==3 for values in by_source.values())
        computed[key]=math.fsum(statistics.fmean(by_source[source]) for source in sources)/4
    result=common_row_summary(pd.DataFrame(rows).assign(paired_delta=lambda frame:frame.paired_delta.astype(float)),main_lock,alternative_lock)
    checked=[]
    for row in result.to_dict("records"):
        assert row["n_sources"]==4
        for metric in ["auroc","auprc","brier"]:
            key=(row["model"],row["truth_regime"],metric)
            assert math.isclose(row[metric],computed[key],abs_tol=1e-12,rel_tol=0)
            checked.append(dict(model=key[0],truth_regime=key[1],metric=metric,paired_delta=computed[key]))
    assert len(checked)==30
    branches[kind]={"status":"PASS","eligible_sources":sources,"checked_summary_values":30,"paired_csv_sha256":digest(path),"checks":checked}
audit_path=root/"reports/COMMON_ROW_SUMMARY_AUDIT.json"
archive=root/"reports/history/COMMON_ROW_SUMMARY_AUDIT_author_only.json"
if not archive.exists():
    archive.write_bytes(audit_path.read_bytes())
report={"status":"PASS","checked_utc":dt.datetime.now(dt.timezone.utc).isoformat(),"qualified_source_count":4,"checked_summary_values":60,"branches":branches,"scope":"Independent standard-library aggregation of all models, both truths and three metrics over frozen qualified sources"}
audit_path.write_text(json.dumps(report,indent=2)+"\n")
primary=list(csv.DictReader((root/"reports/final/training_budget_audit.csv").open()))
alternative=read("reports/DD_ORIGINAL_NEURAL_RUNTIME_AUDIT.json")["trajectories"]
budget=[]
for fold in sorted({row["fold"] for row in primary}):
    left=[row for row in primary if row["fold"]==fold]
    right=[row for row in alternative if row["fold"]==fold]
    entry={"fold":fold}
    for field in ["training_rows","groups","updates","exposures"]:
        a={int(row[field]) for row in left}
        b={int(row[field]) for row in right}
        assert len(a)==len(b)==1,(fold,field)
        entry["primary_"+field]=a.pop()
        entry["dd_original_"+field]=b.pop()
    assert entry["dd_original_training_rows"]-entry["primary_training_rows"]==4312
    budget.append(entry)
with (root/"reports/final/dd_training_budget_comparison.csv").open("w") as handle:
    writer=csv.DictWriter(handle,fieldnames=list(budget[0]))
    writer.writeheader()
    writer.writerows(budget)
print(json.dumps({"status":"PASS","checked_summary_values":60,"dd_fixed_truth_auroc_deltas":[entry for entry in branches["dd_original"]["checks"] if entry["truth_regime"]=="fixed_primary_truth" and entry["metric"]=="auroc"],"training_budgets":budget}))

